var ITEMS=[["What nurses do","Nurses assess patients, administer treatments, monitor conditions, educate families, and coordinate care \u2014 the largest healthcare profession and its backbone. Paths run from CNA to LPN to RN to nurse practitioner, each w"], ["Key skills","Head-to-toe assessment, medication administration (the five rights), IV starts, wound care, patient education, charting accurately, prioritizing under pressure, and therapeutic communication. Critical thinking saves live"], ["Tools of the trade","Stethoscope, blood pressure cuff, penlight, trauma shears, quality scrubs and shoes, a reliable watch with a second hand, pocket references, and increasingly: the EHR system. A good stethoscope is worth the money."], ["A day in the life","Shift handoff report, patient rounds and assessments, med passes, procedures and admissions, family updates, endless charting, and the next handoff. Twelve-hour shifts are standard in hospitals."], ["Getting started","CNA programs take weeks and get you in the door. LPN programs about a year. RN via ADN (2 years) or BSN (4 years), then the NCLEX exam. BSN opens the most doors long-term."], ["Pro tips","Cluster your care to protect rest time. Chart in real time \u2014 memory lies. Ask questions; the only dumb one is the unasked. Take care of your back and your sleep. Find your specialty by trying units."], ["CNA","Profession term \u2014 CNA: Certified Nursing Assistant: basic patient care."], ["LPN","Profession term \u2014 LPN: Licensed Practical Nurse: supervised nursing care."], ["RN","Profession term \u2014 RN: Registered Nurse: full-scope nursing practice."], ["NP","Profession term \u2014 NP: Nurse Practitioner: advanced practice, diagnosing and prescribing."], ["NCLEX","Profession term \u2014 NCLEX: The national licensing exam for nurses."], ["Vitals","Profession term \u2014 Vitals: Temperature, pulse, respirations, blood pressure, pain, oxygen."], ["Five rights","Profession term \u2014 Five rights: Right patient, drug, dose, route, time for medications."], ["SBAR","Profession term \u2014 SBAR: Handoff format: Situation, Background, Assessment, Recommendation."], ["Code blue","Profession term \u2014 Code blue: Cardiac arrest emergency call."], ["Rapid response","Profession term \u2014 Rapid response: Early-warning team before a code."], ["EHR","Profession term \u2014 EHR: Electronic health record charting system."], ["MAR","Profession term \u2014 MAR: Medication administration record."], ["PRN","Profession term \u2014 PRN: As needed medication orders."], ["NPO","Profession term \u2014 NPO: Nothing by mouth orders."], ["Isolation precautions","Profession term \u2014 Isolation precautions: Infection-control protocols by transmission type."], ["Fall precautions","Profession term \u2014 Fall precautions: Safety measures for at-risk patients."], ["Discharge planning","Profession term \u2014 Discharge planning: Coordinating safe transitions home."], ["Triage","Profession term \u2014 Triage: Prioritizing patients by urgency."], ["Compassion fatigue","Profession term \u2014 Compassion fatigue: The burnout of caring professions; real and addressable."]];
